export class Schema {
  constructor(fields = {}) {
    this.fields = { ...fields };
  }

  toString() {
    const fieldNames = Object.keys(this.fields).map((name) => `'${name}'`).join(', ');
    return `<Schema: [${fieldNames}]>`;
  }
}

