import { formatError, formatHelp } from './cli_format.mjs';

export class CliExit extends Error {
  constructor(code, { stdout = '', stderr = '' } = {}) {
    super('CLI exited');
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

function isNegativeNumber(token) {
  return /^-\d+(?:\.\d+)?(?:[eE][+-]?\d+)?$|^-\.\d+(?:[eE][+-]?\d+)?$/.test(token);
}

function startsHelpOption(token) {
  return token === '-h' || token === '--help' || (token.startsWith('--') && '--help'.startsWith(token));
}

function requiresValue(token) {
  return token === undefined || (token.startsWith('-') && token !== '-' && !isNegativeNumber(token));
}

export function parseTest3Args(argv, prog) {
  let aValue;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (startsHelpOption(token)) {
      throw new CliExit(0, { stdout: formatHelp(prog) });
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (requiresValue(next)) {
        throw new CliExit(2, {
          stderr: formatError(prog, 'argument --a: expected one argument'),
        });
      }

      aValue = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  // Match argparse precedence: required-option failures surface before extras.
  if (aValue === undefined) {
    throw new CliExit(2, {
      stderr: formatError(prog, 'the following arguments are required: --a'),
    });
  }

  if (extras.length > 0) {
    throw new CliExit(2, {
      stderr: formatError(prog, `unrecognized arguments: ${extras.join(' ')}`),
    });
  }

  return { a: aValue };
}

