import { parseTest3Args, CliExit } from './lib/cli_parse.mjs';
import { basename } from './lib/path_utils.mjs';
import { Schema, TEXT } from './lib/whoosh_fields.mjs';
import { StemmingAnalyzer } from './lib/whoosh_analysis.mjs';

export function main(argv = process.argv.slice(2), io = process) {
  const prog = basename(process.argv[1] ?? 'test3.mjs');

  try {
    parseTest3Args(argv, prog);
  } catch (error) {
    if (error instanceof CliExit) {
      if (error.stdout !== '') {
        io.stdout.write(error.stdout);
      }

      if (error.stderr !== '') {
        io.stderr.write(error.stderr);
      }

      return error.code;
    }

    throw error;
  }

  const analyzer = new StemmingAnalyzer();
  const schema = new Schema({ content: TEXT({ analyzer }) });
  io.stdout.write(`${schema}\n`);
  return 0;
}

const exitCode = main();

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

